import React, { JSX } from 'react'
import { Text } from 'react-native'
import type { SvgProps } from 'react-native-svg'

import { OptionalReactNativeSvg } from '../optional/OptionalReactNativeSvg'
import { createSafeStyleSheet } from './safeStyleSheet'

const Svg = OptionalReactNativeSvg?.Svg as React.ComponentType<SvgProps> | undefined
const Path = OptionalReactNativeSvg?.Path as React.ComponentType<Record<string, unknown>> | undefined

const getFallbackSize = (value: unknown, fallback: number): number => {
  if (typeof value === 'number') {
    return value
  }

  if (typeof value === 'string') {
    const parsed = Number.parseInt(value, 10)
    return Number.isNaN(parsed) ? fallback : parsed
  }

  return fallback
}

const getFallbackColor = (fill: unknown): string => {
  return typeof fill === 'string' && fill !== 'none' ? fill : 'black'
}

const getFallbackFontSize = (label: string, height: number): number => {
  return label.length > 1 ? Math.round(height * 0.55) : height
}

const renderFallbackIcon = ({
  label,
  fill,
  height,
}: {
  label: string
  fill?: unknown
  height: number
}): JSX.Element => (
  <Text
    allowFontScaling={false}
    style={[
      styles.fallbackIcon,
      {
        color: getFallbackColor(fill),
        fontSize: getFallbackFontSize(label, height),
        height,
        lineHeight: height,
        width: height,
      },
    ]}
  >
    {label}
  </Text>
)

const renderSvgIcon = ({
  props,
  height,
  width,
  viewBox,
  pathProps,
  fallback,
}: {
  props: SvgProps
  height: string
  width: string
  viewBox: string
  pathProps: Record<string, unknown>
  fallback: string
}): JSX.Element => {
  if (!Svg || !Path) {
    return renderFallbackIcon({
      label: fallback,
      fill: (props as { fill?: unknown }).fill,
      height: getFallbackSize(props.height ?? height, 48),
    })
  }

  return (
    <Svg height={height} viewBox={viewBox} width={width} {...props}>
      <Path {...pathProps} />
    </Svg>
  )
}

